697	# chain length, and a precheck must never crash on a valid long chain.
698	# Stack frames are ('enter',node)/('exit',node) pairs: a node is colour 1
699	# exactly while its 'exit' frame is still on the stack, so popping an 'enter'
700	# for a colour-1 node proves a path from that node back to itself.
701	function Test-GraphHasCycleFrom { param([string]$Node,[hashtable]$Adjacency,[hashtable]$Visit)
702	  if ($Visit[$Node]) { return $false }
703	  $stack = [Collections.Generic.Stack[object[]]]::new()
