716	$visitState=@{}
717	foreach($node in $nodes){ if(Test-GraphHasCycleFrom -Node $node -Adjacency $adjacency -Visit $visitState){ Fail 'Blockers dependency graph contains a cycle' } }
718	$tasksHash=(Get-FileHash -LiteralPath $tasks -Algorithm SHA256).Hash.ToLower(); $requirementsHash=(Get-FileHash -LiteralPath $requirements -Algorithm SHA256).Hash.ToLower(); $acceptanceHash=(Get-FileHash -LiteralPath $acceptance -Algorithm SHA256).Hash.ToLower(); $designHash=(Get-FileHash -LiteralPath $design -Algorithm SHA256).Hash.ToLower()
719	# WFI-025: a mixed-status plan records the normalized digest (see the helper's
720	# header); a uniform plan keeps today's raw behaviour byte-for-byte.
721	$tasksHashForm = 'raw'
722	if (Test-TasksStatusesMixed $tasks) {
723	  $tasksHashForm = 'normalized'
724	  $tasksHash = Get-TasksNormalizedHash $tasks
725	}
726	$traceabilityHash = ''
