728	if ($fullProfile) {
729	  $traceabilityHash = (Get-FileHash -LiteralPath $traceability -Algorithm SHA256).Hash.ToLower()
730	  foreach ($name in $layerNames) { $layerHashes[$name] = (Get-FileHash -LiteralPath (Join-Path $spec $name) -Algorithm SHA256).Hash.ToLower() }
731	  & (Join-Path $PSScriptRoot 'validate-layer-traceability.ps1') -Path $traceability -RequirementsPath $requirements
732	}
733	$calibration = Join-Path $root 'plugins/sdd-review-loop/references/reviewer-calibration.md'
734	if (-not (Test-Path -LiteralPath $calibration -PathType Leaf) -or (Get-Item -LiteralPath $calibration).LinkType) { Fail 'plugins/sdd-review-loop/references/reviewer-calibration.md not found' }
735	$calibrationHash = (Get-FileHash -LiteralPath $calibration -Algorithm SHA256).Hash.ToLower()
736	$specReviewedRequirementsHash = Get-ReviewedHash $requirements 'Spec-Review-Status' 'Pending'
737	$implReviewedDesignHash = Get-ReviewedHash $design 'Impl-Review-Status' 'Pending'
738	Require-Pass (Join-Path $root "reports/spec-review/$Feature") 'spec' $Feature $specReviewedRequirementsHash $acceptanceHash '' $requirementsHash ''
739	Require-Pass (Join-Path $root "reports/impl-review/$Feature") 'impl' $Feature $requirementsHash $acceptanceHash $implReviewedDesignHash $requirementsHash $designHash
740	$riskScript = Join-Path $root 'plugins/sdd-quality-loop/scripts/check-risk.ps1'
741	if (-not (Test-Path -LiteralPath $riskScript -PathType Leaf)) { Fail 'shared risk gate is missing' }
742	& $riskScript -TasksPath $tasks
743	if ($LASTEXITCODE -ne 0) { Fail 'Risk/Required Workflow mismatches must be fixed before creating evidence' }
744	# WFI-030 STEP 2b, twin of the awk block in task-review-precheck.sh. Detection
745	# only: the exit code is unaffected by a non-empty result. Continuation lines
746	# are joined into whole items before matching, because two of the three known
747	# real cases put the artifact name and the write verb on different lines.
748	$fdwLines = [IO.File]::ReadAllLines($tasks)
749	$fdwItems = @(); $fdwTask = ''; $fdwIn = $false; $fdwCur = $null
750	for ($fdwI = 0; $fdwI -lt $fdwLines.Count; $fdwI++) {
751	  $fdwL = $fdwLines[$fdwI]
752	  if ($fdwL -match '^##\s+(T-\d+)') {
753	    if ($fdwCur) { $fdwItems += $fdwCur; $fdwCur = $null }
754	    $fdwTask = $Matches[1]; $fdwIn = $false; continue
755	  }
756	  if ($fdwL -match 'Done When') {
757	    if ($fdwCur) { $fdwItems += $fdwCur; $fdwCur = $null }
758	    $fdwIn = $true; continue
759	  }
760	  if ($fdwL -match '^(##|###)\s' -or $fdwL -match '^[A-Za-z][A-Za-z ]*:') {
761	    if ($fdwCur) { $fdwItems += $fdwCur; $fdwCur = $null }
762	    $fdwIn = $false; continue
763	  }
764	  if (-not $fdwIn) { continue }
765	  if ($fdwL -match '^- \[') {
766	    if ($fdwCur) { $fdwItems += $fdwCur }
767	    $fdwCur = [ordered]@{ task = $fdwTask; line = ($fdwI + 1); item = $fdwL }; continue
768	  }
769	  if ($fdwL -match '^[ \t]+\S') { if ($fdwCur) { $fdwCur.item = $fdwCur.item + ' ' + $fdwL.TrimStart() }; continue }
770	  if ($fdwCur) { $fdwItems += $fdwCur; $fdwCur = $null }
771	}
